INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61904798', 61904798, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'BADAN PELAYANAN PENGADAAN BARANG/JASA', 'Penyediaan Tenaga Ahli Data Analyst PIP', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 101750000, 'December 2025', 'APBD', 1, 1, '10 OB', 'a. Melaksanakan Pengolahan dan Menganalisa data Pengadaan Barang/Jasa yang bersumber dari data Pengadaan Barang/Jasa (tidak terbatas dari ISB LKPP) b. Skenario pengambilan keputusan berdasarkan data Pengadaan Barang/Jasa yang bersumber dari data Pengadaan Barang/Jasa (tidak terbatas dari ISB LKPP) c. Melakukan Analisa terkait data yang akan digunakan sebagai metode penentu keputusan d. Mengidentifikasi masalah hasil analisa data e. Memberi saran kepada programmer berdasarkan hasil temuan Analisa data yang telah diuji dengan tujuan untuk membantu meningkatkan pelayanan f. Mampu mengoptimasi database g. Mampu melakukan Query Database h. Mampu melakukan Cleansing data sesuai kebutuhan i. Memberikan saran atau ide kepada atasan agar BPPBJ dapat lebih maju dan berkembang j. Menyusun atau menyempurnakan metode/prosedur analisa data dan publikasi data k. Berbagi pengetahuan mengenai pengolahan dan analisa data Pengadaan Barang/Jasa l. Mampu menyajikan data dalam bentuk infografis m. Membuat buku panduan/manual book n. Menyajikan hasil pekerjaan dalam bentuk tulisan/paper, presentasi serta softcopy o. Melaksanakan pekerjaan sesuai arahan pimpinan p. Memberikan knowledge sharing dalam rangka alih pengetahuan', 'Berpendidikan minimal S1 Statisika, Memiliki pengalaman minimal 3 tahun dalam bidang Data Analyst, Diutamakan mempunyai pengalaman kerja di Pemerintahan, Menguasai Microsoft Excel, Memahami database PostgreSQL, Mampu Query dan Cleansing data, Menguasai aplikasi pembuatan Visualisasi Dasboard tableau, Menguasai bahasa pemprograman Python.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 40044);
