INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61911276', 61911276, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'KELURAHAN HALIM PERDANA KUSUMA - JAKTIM', 'Belanja Jasa Tenaga Penanganan Prasarana dan Sarana Umum', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Timur (Kota)', 5472315654, 'December 2025', 'APBD', 1, 1, '1 Paket', 'Jenis Pekerjaan di bagi kedalam 4 Rumpun Kategori Pekerjaan : 1. Tenaga Adminitrasi Tingkat Kelurahan 2. Tenaga Kebersihan Tipe D 3. Tenaga Keamanan Tipe A 4. Tenaga Kebersihan (PPSU)', '1. Ruang lingkup pelaksanaan kegiatan tenaga administrasi tingkat kelurahan meliputi : a. Pengadministrasi kegiatan terkait Penanganan Prasarana Sarana Umum (PPSU); b. Pengadministrasi Pelayanan Kelurahan; c. Tenaga administrasi surat masuk dan keluar; d. Melaksanakan kegiatan pengelolaan arsip; e. Melaksanakan tugas kedinasan dari atasan langsung. 2. Ruang lingkup pelaksanaan kegiatanTenaga Kebersihan Tipe D meliputi : a. Melaksanakan kebersihan gedung, halaman dan taman Kantor; b. Melakukan pengecekkan kebersihan gedung, halaman dan taman Kantor; c. Melakukan pengecekkan toilet seluruh gedung; d. Menyediakan air minum untuk pegawai; e. Melakukan tugas arahan langsung pimpinan; 3. Ruang lingkup pelaksanaan kegiatan Tenaga Keamanan Tipe A Meliputi : a. Melaksanakan pengamanan secara menyeluruh di Kantor Kelurahan; b. Melakukan pemeriksaan pada tamu / pemilik yang akan masuk ke area kerja; c. Menanyakan keperluan tamu; d. Membantu mengarahkan tamu atas keperluan/tujuan tamu; e. Melaksanakan tugas arahan langsung dari pimpinan. 4. Ruang lingkup pelaksanaan kegiatan Tenaga Kebersihan (PPSU) Meliputi : a. Penanganan prasarana dan sarana jalan/gang; b. Penanganan prasarana dan sarana saluran; c. Penanganan prasarana dan sarana taman; d. Penanganan prasarana dan sarana kebersihan; e. Penanganan prasarana dan sarana penerangan jalan umum; dan f. Tugas Non Fisik Perintah Lurah sesuai kebutuhan organisasi.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 41757);
