INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61911192', 61911192, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'SUKU DINAS KOMUNIKASI, INFORMATIKA DAN STATISTIK KOTA - JAKUT', 'PJLP Layanan E-Government', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Utara (Kota)', 109892250, 'December 2025', 'APBD', 1, 1, '1 Orang x 13 Bulan', '1. Melakukan pemrograman, pembaharuan, penyempurnaan dan pemeliharaan sistem website / portal; 2. Melakukan pengembangan, pembaharuan aplikasi pada subdomain sesuai arahan webmaster; 3. Melakukan konfigurasi, monitoring dan pemeliharaan server, storage dan keamanan akses data website/portal setiap harinya; 4. Melakukan manajemen domain, hosting dan SEO, melakukan pemrograman dan pengaturan, pemeliharaan webserver; 5. Melakukan Analisa kebutuhan, melakukan konfigurasi, pemeliharaan, perbaikan hardware server.', '1. Pendidikan minimal D3 Jurusan Teknik Komputer/Teknik Informatika /Sistem Informasi/Ilmu Komputer; 2. Memiliki pengalaman kerja di bidang pemrograman website minimal 1 (satu) tahun yang dibuktikan dengan surat keterangan pengalaman kerja; 3. Memiliki kemampuan merancang, membangun, mengembangkan, memelihara dan mengopimalkan fungsi website/microsite sesuai dengan kebutuhan; 4. Memahami metode pengembangan website dan integrasi; 5. Menguasai HTML dan Framework Bootstrap (front-end); 6. Menguasai bahasa pemrograman PHP (Native dan Framework Laravel) dan Basis Data MySql (back- end); 7. Mampu menjaga layanan publikasi melalui Portal Resmi Kota Administrasi Jakarta Utara agar tetap berfungsi dengan optimal setiap saat; 8. Mampu melakukan update data/informasi yang disajikan dalam website; 9. Melakukan monitoring penggunaan website dan memaksimalkan akses website; 10. Mampu mendukung penerapan Sistem Pemerintahan Berbasis Elektronik (e-Government) terkait aplikasi.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 41837);
