INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61911135', 61911135, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'SUKU DINAS KOMUNIKASI, INFORMATIKA DAN STATISTIK KOTA - JAKUT', 'PJLP Layanan Keamanan Informasi', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Utara (Kota)', 109892250, 'December 2025', 'APBD', 1, 1, '1 Orang x 13 Bulan', '1. Mengelola insiden kegiatan teknologi informasi; 2. Monitoring perangkat keamanan jaringan sesuai dengan lingkup tugasnya; 3. Melakukan pendampingan dalam penerbitan dan penggunaan Tanda Tangan Elektronik di lingkungan UKPD/SKPD Kota Administrasi Jakarta Utara; 4. Melakukan instalasi / konfigurasi / pemasangan / penggunaan / pengoperasian peralatan keamanan jaringan dan perangkat lunak (antivirus) pada client/personal computer.', '1. Pendidikan minimal D3 diutamakan Jurusan Teknik Komputer/Teknik Informatika/Sistem Informasi/Ilmu Komputer; 2. Memiliki pengalaman kerja sebagai Technical Support di bidang IT minimal 1 (satu) tahun yang dibuktikan dengan surat keterangan pengalaman kerja; 3. Menguasai Sistem Operasi Windows dan Linux; 4. Mampu melakukan pengelolaan perangkat lunak pada Server (Sistem Operasi, Web Server dan Database) meliputi instalasi, konfigurasi, peningkatan kinerja server (tunning), pembaharuan (updating), backup dan restore serta troubleshooting; 5. Mampu melakukan pengelolaan perangkat lunak Antivirus meliputi instalasi pada client, monitoring Dashboard perangkat lunak Antivirus pada Server serta troubleshooting; 6. Memiliki kemampuan dalam menganalisis permasalahan keamanan informasi serta upaya penanganannya; 7. Mampu mengoperasikan perangkat lunak Virtual Meeting, Video Streaming dan perangkat pendukung lainnya; 8. Mampu mendukung penerapan Sistem Pemerintahan Berbasis Elektronik (e-Government) terkait keamanan informasi.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 44679);
