INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62353424', 62353424, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'BADAN KEPEGAWAIAN DAERAH', 'Belanja Jasa Konsultansi Berorientasi Bidang-Telematika Sub Kegiatan Pengelolaan Sistem Informasi Kepegawaian - Tenaga Ahli Quality Assurance 1', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 61050000, 'December 2025', 'APBD', 1, 1, '1 (orang) x 6 (bulan)', '1. Mempelajari dan memahami kebutuhan sistem yang akan diuji (spec, flow, SRS). 2. Menyusun rencana pengujian (test plan) dan skenario pengujian (test case). 3. Melakukan pengujian aplikasi (manual test dan/atau automated test) sesuai kebutuhan. 4. Mengidentifikasi bug, error, atau ketidaksesuaian fungsi sistem, serta menyusun laporan hasil uji. 5. Berkoordinasi dengan programmer dan sistem analis dalam proses perbaikan error. 6. Menguji ulang aplikasi setelah perbaikan (retesting dan regression testing). 7. Memberikan rekomendasi perbaikan untuk meningkatkan kualitas, keamanan, dan pengalaman pengguna (UX). 8. Mendokumentasikan proses pengujian dan hasil evaluasi sistem secara berkala.', 'Pengelolaan dan Pengembangan Aplikasi dan Sistem Informasi Kepegawaian (SIMPEG) serta Aplikasi-palikasi pendukung lainnya.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 45267);
