INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61452339', 61452339, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'SUKU DINAS  PERINDUSTRIAN, PERDAGANGAN, KOPERASI, USAHA KECIL DAN MENENGAH KABUPATEN - KEP. SERIBU', 'Penyediaan Jasa Pendamping Kewirausahaan IKM di Wilayah Kepulauan Seribu (Gaji PJLP)', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Adm. Kepulauan Seribu (Kab.)', 574025400, 'December 2025', 'APBD', 1, 1, '8 orang x 13 bulan', 'Penyedia Jasa Lainnya wajib melaksanakan dan menyelesaikan pekerjaan sebagai berikut : a. Melaksanakan kegiatan peningkatan kapasitas wirausaha bagi Pencari Kerja, Wirausaha Pemula dan/atau Wirausaha Naik Kelas yang sudah terdaftar melalui fasilitasi pendaftaran, pelatihan, pendampingan, perizinan, pemasaran, pelaporan keuangan dan pemodalan dengan mekanisme kerja yang ditentukan oleh Dinas Perindustrian, Perdagangan, Koperasi, Usaha Kecil dan Menengah Provinsi DKI Jakarta; b. Melaksanakan kegiatan pendampingan kepada para Wirausaha Pemula maupun Wirausaha Naik Kelas dalam meningkatkan Aset, Omset dan Tenaga Kerja; dan c. Melaporkan hasil pekerjaan sebagaimana dimaksud pada point a dan b secara berjenjang.', 'Persyaratan Umum : 1. Warga Negara Indonesia (WNI); 2. Bertaqwa kepada Tuhan YME, setia dan taat kepada Pancasila, UUD Negara Republik Indonesia Tahun 1945 dan Negara Kesatuan Republik Indonesia; 3. Memiliki KTP DKI Jakarta; 4. Memiliki NPWP Pribadi dan Kepesertaan BPJS (Kesehatan dan Ketenagakerjaan); 5. Tidak pernah dihukum penjara atau kurungan berdasarkan putusan pengadilan, yang dibuktikan dengan Surat Keterangan Catatan Kepolisian / SKCK (Asli), dan diserahkan pada saat Seleksi Kompetensi; 6. Sehat jasmani yang dibuktikan dengan Surat Keterangan Sehat dari Puskesmas/Rumah Sakit Pemerintah (Asli), dan diserahkan pada saat Seleksi Kompetensi; 7. Bebas dari Narkotika (amphetamine, cannaboid, opiate) dan Zat Adiktif lainnya dibuktikan dengan Surat Keterangan Asli dari Instansi yang berwenang dan diserahkan pada saat Seleksi Kompetensi. Persyaratan Khusus : 1. Pria dan Wanita dengan Usia minimal 18 Tahun dan maksimal 56 Tahun per 1 Januari 2026; 2. Pendidikan minimal Sarjana (S1) atau setara (Ijazah dan Transkrip Nilai Asli perlihatkan pada saat Seleksi Kompetensi); 3. Diutamakan bagi yang telah memiliki usaha dan atau pengalaman memberikan pendampingan usaha serta memiliki Sertifikat Pendamping Kewirausahaan: a) Pelamar yang saat ini masih terikat kontrak sebagai PJLP Pendamping Kewirausahaan melampirkan Sertifikat Kompetensi Kewirausahaan dari BNSP dan melampirkan Surat Keterangan memiliki usaha (jika ada); b) Pelamar baru melampirkan Surat Keterangan memiliki usaha dan atau pengalaman dan keterampilan di bidang Kewirausahaan dari Perguruan Tinggi/Lembaga/Instansi Pemerintah/Komunitas di Bidang Kewirausahaan. 4. Mampu mengoperasikan Komputer minimal Program Microsoft Office (Word, Excel, Power Point), mengoperasikan internet dan menguasai aplikasi yang berkaitan dengan pelaksanaan tugas pendamping kewirausahaan; 5. Apabila dinyatakan lulus seluruh tahapan seleksi dan telah ditetapkan secara resmi oleh Pejabat Pengadaan Barang/Jasa, bersedia menandatangani berkas bermaterai sebagai berikut : a) Surat Pernyataan Bermaterai (Rp. 10.000,-) siap ditempatkan dimana saja sesuai penugasan; b) Surat Pernyataan Bermaterai (Rp. 10.000,-) bahwa hanya berkontrak kerja dengan Suku Dinas Perindustrian, Perdagangan, Koperasi, Usaha Kecil dan Menengah Kabupaten Administrasi Kepulauan Seribu dan tidak akan menuntut diangkat menjadi PNS dan Pegawai Pemerintah dengan Perjanjian Kerja (P3K) di kemudian hari; c) Surat Pernyataan Bermaterai (Rp. 10.000,-) tidak menuntut apabila proses rekruitmen PJLP Petugas Pendamping Kewirausahaan dibatalkan karena ketentuan dan keputusan yang ada.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 45417);
