INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62357232', 62357232, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'BADAN PERENCANAAN PEMBANGUNAN DAERAH', 'Penyediaan Tenaga Ahli Pengelolaan Keuangan dan Investasi Daerah 2', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 70950000, 'June 2026', 'APBD', 1, 1, '1 Paket', 'a. Melakukan pendampingan dan dokumentasi rapat teknis pemerintahan dan pengkajian peraturan yang dilaksanakan oleh Bidang Perekonomian; b. Membantu identifikasi isu dan kendala pada pelaksanaan kegiatan Bidang Perekonomian terkait pembangunan daerah; c. Memberikan saran dan pertimbangan terhadap suatu gagasan dan konsep sesuai ruang lingkupnya; d. Membantu Bidang Perekonomian dalam menyusun suatu draft telaahan, analisis dan kajian; e. Melakukan konsultasi, koordinasi dan pertemuan/diskusi internal dengan Perangkat Daerah/Kementerian/ Lembaga/Institusi sesuai kebutuhan pengumpulan bahan materi; f. Melaksanakan dan menyelesaikan pekerjaan sesuai dengan jadwal pelaksanaan pekerjaan yang telah ditetapkan; g. Melaporkan dan mempresentasikan data dan informasi terkait issue/permasalahan kepada Kepala Bidang Perekonomian secara periodik; h. Menghadiri dan melaporkan hasil kegiatan; i. Membantu penyusunan rencana dan konsep implementasi dalam bentuk rekomendasi program atau kegiatan; j. Tugas tambahan lainnya yang disesuaikan dengan kebutuhan Bidang Perekonomian.', 'a. Berlatar belakang pendidikan minimal Sarjana (S1) pada jurusan/program studi Pembangunan Wilayah, Perencanaan Wilayah dan Kota, dan/atau Ekonomi Pembangunan. b. Memiliki spesifikasi bidang Ekonomi–Pembangunan Daerah dan Perencanaan. c. Memiliki pengalaman kerja minimal 5 (lima) tahun di Instansi Pemerintah Daerah, Pemerintah Pusat, Lembaga Negara, atau instansi/perusahaan lainnya. d. Memiliki Sertifikat Keahlian (SKA) yang diterbitkan oleh Lembaga Pengembangan Jasa Konstruksi (LPJK) sebagai bukti kompetensi dan kapabilitas profesi tenaga ahli di bidang jasa non konstruksi. e. Memiliki pengalaman dalam melaksanakan analisis kebijakan dan pengolahan data terkait perencanaan dan pembangunan. f. Memiliki pengalaman dalam penyusunan dokumen perencanaan Pemerintah Daerah dan/atau policy brief/policy paper. g. Memiliki pengalaman dalam analisis lintas sektor. h. Mampu mengoperasikan Microsoft Office dan Google Workspace dengan sangat baik. i. Mampu mengoperasikan program pengolahan dan penyajian data lainnya seperti ArcGIS, Tableau, SPSS, Analysis Hierarchy Process (AHP), Expert Choice, dan lain-lain. j. Kepemilikan peralatan kerja pribadi yang diperlukan untuk menunjang pelaksanaan tugas (contoh: Laptop) akan menjadi nilai tambah. k. Mahir dalam berbahasa Inggris (minimal skor TOEFL 500).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 45463);
