INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61857212', 61857212, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'PUSAT DATA DAN INFORMASI CIPTA KARYA, TATA RUANG DAN PERTANAHAN', 'Tenaga Sub Profesional - Facilitator (Pengelolaan Kearsipan dan Digitalisasi Arsip Dokumen Teknis dan Perizinan Tata Ruang dan Bangunan)', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 847440000, 'December 2025', 'APBD', 1, 1, '12 Orang x 12 Bulan', 'Ruang lingkup pekerjaan Kegiatan Pengelolaan Digitalisasi Arsip Dokumen Teknis dan Perizinan Tata Ruang dan Bangunan (Facilitator) adalah sebagai berikut: a. Melakukan kegiatan alih media Dokumen Teknis dan Perizinan; b. Melakukan input dan pengelolaan data hasil scan ke system; c. Mempertanggung jawabkan untuk memastikan kualitas produk dan informasi; d. Menjaga dan meningkatkan kinerja hasil input; e. Melakukan analisa data sesuai kebutuhan layanan terhadap produk yang akan dikembangkan; f. Memberikan dukungan mengupdate data hasil scan di lingkungan kerja Pusat Data dan Informasi Cipta Karya, Tata Ruang dan Pertanahan; g. Melakukan penataan kearsipan; h. Memperbaiki kesalahan dengan membuat perubahan yang sesuai dan memeriksa kembali hasil scan untuk memastikan bahwa hasil yang diinginkan telah berhasil; i. Melakukan membuat analisa terhadap permasalahan; j. Berkonsultasi dengan tim dan membantu tenaga ahli mendefinisikan dan menyelesaikan masalah dalam menjalankan program-program komputer; k. Melaporkan dan mempertanggung jawabkan pelaksanaan tugas; l. Melaksanakan tugas lainnya yang ditetapkan oleh pimpinan/atasan sesuai kewenangan.', 'Spesifikasi Teknis Kegiatan Pengelolaan Digitalisasi Arsip Dokumen Teknis dan Perizinan Tata Ruang dan Bangunan (Facilitator) ini adalah : a. Memahami mekanisme pengelolaan kearsipan; b. Melakukan pemindaian (scanning) dokumen teks dan gambar teknis dengan standar minimal: Resolusi 300-600 dpi dengan format hasil PDF; c. Memastikan kelengkapan setiap arsip sebelum dan sesudah digitalisasi; d. Menguasai Adobe Acrobat, aplikasi image processing dan Microsoft Office.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 45512);
