INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61451618', 61451618, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'PUSAT DATA DAN INFORMASI CIPTA KARYA, TATA RUANG DAN PERTANAHAN', 'Tenaga Ahli Publikasi dan Kehumasan (Team Leader Content Creator & Publikasi)', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 151800000, 'November 2025', 'APBD', 1, 1, '1 Orang x 12 Bulan', '1) Memimpin dan mengoordinasikan tim kreatif lintas bidang (desain grafis, video editor, copywriter, dan social media specialist) dalam perancangan konsep konten, produksi media, serta publikasi visual yang berhubungan dengan substansi materi yang akan disampaikan ke publik. 2) Mengembangkan konsep visual dan narasi komunikasi yang mampu menerjemahkan materi teknis ketentuan bangunan gedung, tata ruang, prosedur perizinan bangunan, produk layanan digital dan regulasi / kebijakan publik menjadi konten edukatif, menarik, dan mudah dipahami masyarakat. 3) Mempersiapkan, mengarahkan, dan memverifikasi materi publikasi digital dan non-digital, termasuk desain grafis, video, infografis, foto, dan artikel agar sesuai dengan identitas visual dan pedoman komunikasi instansi. 4) Mengarahkan proses produksi video kreatif — mulai dari penyusunan storyboard hingga proses editing dan finishing output audiovisual. 5) Menguasai dan mengarahkan penggunaan perangkat lunak desain grafis, multimedia, motion graphic, 3d modeling, dan visual rendering seperti Adobe Creative Suite (Photoshop, Illustrator, Premiere Pro, dan After Effects), CapCut, Canva, Sketch Up, Blender, Lumion atau perangkat sejenis untuk memastikan kualitas hasil produksi. 6) Mengembangkan strategi publikasi konten media sosial yang konsisten, relevan dengan tren, dan mendukung branding positif instansi, serta melakukan evaluasi performa konten dan engagement audiens. 7) Memimpin arah artistik (creative direction) pada seluruh bentuk publikasi dan kegiatan kehumasan, termasuk memastikan integrasi visual antara desain, substansi materi, dan pesan komunikasi publik. 8) Melakukan pengawasan teknis dokumentasi lapangan seperti fotografi, videografi, serta penggunaan drone untuk mendukung kebutuhan visual proyek dan publikasi kegiatan. 9) Mempresentasikan ide dan konsep publikasi kepada pimpinan, memberikan rekomendasi strategi komunikasi kreatif, serta melakukan revisi atau penyempurnaan konsep sesuai umpan balik. 10) Bertanggung jawab dalam koordinasi dengan Team Leader Production dan Event dan pembagian tugas kepada Senior Content Creator, Senior Kehumasan, dan tim Content Creator dan Kehumasan lainnya untuk memastikan seluruh kegiatan produksi dan publikasi berjalan efektif dan tepat waktu. 11) Menyusun laporan hasil kegiatan publikasi secara berkala, serta memberikan rekomendasi pengembangan strategi komunikasi kreatif untuk periode berikutnya.', 'S1 Program Studi Arsitektur / Desain Komunikasi Visual / Ilmu Komunikasi, dan/atau semua jurusan yang setara/relevan dengan pemahaman perencanaan tata ruang kota dan ketentuan bangunan, desain komunikasi visual, konten kreatif dan komunikasi publik serta memiliki pengalaman kerja minimal 6 (enam) tahun dalam bidang Publikasi dan Kehumasan serta Tata Ruang dan Bangunan', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 45688);
