INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61471728', 61471728, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'PUSAT DATA DAN INFORMASI CIPTA KARYA, TATA RUANG DAN PERTANAHAN', 'Tim Pembangunan, Pengembangan dan Pengelolaan Sistem Informasi Geografis Jakarta Satu - Senior GIS Research and Innovation', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 204600000, 'November 2025', 'APBD', 1, 1, '1 orang/12 bulan', '1. Bertanggung jawab terhadap seluruh pelaksanaan pekerjaan sesuai dengan spesifikasi teknis yang ditetapkan; 2. Membuat jadwal pekerjaan, memberikan tugas sampai dengan memantau dan mengendalikan hasil pekerjaan tim; 3. Melakukan supervisi proses eksplorasi pemanfaatan Teknologi kecerdasan buatan / Geospatial Artificial Intelligence (GeoAI) untuk pengembangan riset dan analisis spasial; 4. Melakukan supervisi proses pengembangan Peta Dasar 3D Jakarta serta pemanfaatannya untuk pengembangan Peta 3D Jakarta; 5. Membantu integrasi dan melakukan analisis spasial tingkat lanjut terhadap data GIS dari berbagai sumber; 6. Melakukan implementasi perangkat lunak dan data hasil pengembangan riset dan inovasi spasial ke sistem database dan server Jakarta Satu; 7. Mendokumentasikan kegiatan riset dan inovasi, publikasi dan sharing knowledge menjadi sebuah laporan kegiatan; 8. Berkolaborasi dan berkoordinasi dengan tim lain Jakarta Satu untuk implementasi hasil riset GIS ke dalam portal Jakarta Satu. 9. Melaksanakan perumusan konsep dan pelaksanaan kegiatan terkait Jakarta Satu Festival 10. Memastikan seluruh pekerjaan dikerjakan secara efektif dan efisien; 11. Melaksanakan monitoring dan evaluasi internal tim; 12. Melakukan koordinasi dengan tim lain Jakarta Satu untuk pengembangan geospasial Jakarta Satu; 13. Melaporkan dan mempertanggungjawabkan pelaksanaan tugas; 14. Melaporkan dan mempertanggungjawabkan pelaksanaan tugas setiap bulanan dan tahunan; 15. Melaksanakan tugas lainnya yang ditetapkan oleh pimpinan/atasan sesuai kewenangan', 'Tenaga Ahli Muda S2 Pengalaman Minimal 3 Tahun (Jasa Konsultansi Perorangan Non Konstruksi)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 46416);
