INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61466426', 61466426, 'analyze_legacy', 'Kementerian Agama', 'central', 'IAIN MANADO 426251', 'Jasa Konsultansi Perencanaan Pembangunan Gedung Laboratorium Terpadu IAIN Manado T.A. 2026', 'Jasa Konsultansi', 'Seleksi', 'Sulawesi Utara, Manado (Kota)', 3028024000, 'November 2024', 'APBN - SBSN (T)', 0, 1, '1 LS', 'Uraian Pekerjaan Jasa Konsultansi Perencanaan Pembangunan Gedung Laboratorium TerpaduIAIN Manado 1. Kajian dan Analisis Kebutuhan a. Melakukan studi kebutuhan ruang dan fasilitaslaboratorium terpadu sesuai dengan program pendidikan dan kegiatan akademik di IAIN Manado.b.Mengidentifikasi kebutuhan laboratorium berdasarkan standar dan regulasi yang berlaku. 2.Perencanaan Konsep dan Desain Awal a. Mengembangkan konsep desain awal sesuai dengankebutuhan fungsional dan teknis. b. Menyusun sketsa awal tata ruang dan tata letak gedunglaboratorium. 3. Perencanaan Arsitektur dan Tata Letak a. Menghasilkan gambar desain arsitekturlengkap termasuk denah, tampak, potongan, dan RAB awal. b. Menyusun rencana sirkulasi dantata ruang yang efisien dan memenuhi aspek keselamatan dan kenyamanan. 4. PerencanaanStruktur dan MEP (Mechanical, Electrical, Plumbing) a. Menyiapkan gambar struktur gedung sesuaistandar kekuatan dan keamanan bangunan. b. Menyusun perencanaan sistem Mechanical,Electrical, dan Plumbing (MEP) yang efisien dan ramah lingkungan. 5. Perizinan dan DokumenAdministrasi a. Membantu pengurusan izin pembangunan sesuai dengan regulasi setempat. bMenyusun dokumen perencanaan lengkap untuk tahap pembangunan. 6. Pengendalian danSupervisi Desain a. Melakukan pengawasan terhadap pelaksanaan desain agar sesuai standar danspesifikasi. b. Menyediakan layanan konsultansi selama proses tender dan pembangunan. 7.Persiapan Dokumen Tender a. Menyusun dokumen tender dan spesifikasi teknis sebagai acuanpelaksanaan pekerjaan. 8. Pelaporan dan Konsultasi Teknis a. Menyediakan laporan progres dankonsultasi teknis selama tahap perencanaan dan pelaksanaan pembangunan.', 'Spesifikasi Pekerjaan Jasa Konsultansi Perencanaan Pembangunan Gedung Laboratorium TerpaduIAIN Manado 1. Lingkup Pekerjaan Kajian kebutuhan dan studi kelayakan Perencanaan konsep dandesain awal Pengembangan gambar kerja detail (arsitektur, struktur, MEP) Penyusunan dokumenperizinan Pengawasan dan pengendalian desain Dokumentasi tender dan administrasi 2. Standardan Ketentuan Teknis Mengacu pada Standar Nasional Indonesia (SNI) terkait perencanaan danpembangunan gedung Memenuhi standar keselamatan dan kesehatan kerja (K3) Sesuai regulasilingkungan dan tata ruang setempat Menggunakan prinsip ramah lingkungan dan efisiensi energi3. Kualitas dan Dokumen Gambar Gambar kerja lengkap dan detail (rencana, tampak, potongan,detail teknis) Rencana instalasi mekanikal dan elektrikal RAB dan analisis biaya lengkap Dokumendokumen administrasi dan izin pembangunan 4. Metodologi Kerja Pendekatan partisipatifmelibatkan stakeholder terkait Penggunaan perangkat lunak desain arsitektur dan struktur(AutoCAD, Revit, SAP2000, dll.) Pelaporan progres secara berkala 5. Dokumentasi danPengendalian Mutu Dokumen lengkap harus disusun sesuai ketentuan Melakukan review danvalidasi desain secara internal dan eksternal Menyediakan dokumentasi revisi jika diperlukan', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 46843);
