INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61495539', 61495539, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'PUSAT DATA DAN INFORMASI CIPTA KARYA, TATA RUANG DAN PERTANAHAN', 'Tim Pembangunan, Pengembangan dan Pengelolaan Sistem Informasi Geografis Jakarta Satu - Junior GIS Developer and Education - 2', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 122100000, 'November 2025', 'APBD', 1, 1, '1 orang x 12 bulan', '1. Bertanggung jawab terhadap seluruh pelaksanaan pekerjaan sesuai dengan spesifikasi teknis yang ditetapkan; 2. Melakukan supervisi proses integrasi, mastering, pengolahan, dan pengelolaan manajemen data, analisa data dan metadata data, processing data dan transformasi data dan informasi spasial kepada Sespro dan Aspro agar data 3. dapat masuk ke dalam portal Jakarta Satu; 4. Melakukan quality control (QC) terhadap data dan informasi spasial yang dikerjakan Sespro dan Aspro untuk menjamin akurasi, kelengkapan, konsistensi, dan keterbaruan sesuai dengan standarisasi yang telah ditetapkan; 5. Membantu pelaksanaan workshop, sosialisasi, atau pelatihan terkait akuisisi, integrasi, dan pengolahan data geospasial bagi seluruh Perangkat Daerah/Unit Perangkat Daerah di lingkungan Pemerintah Provinsi DKI Jakarta; 6. Membantu melakukan monitoring seluruh data di Jakarta Satu; 7. Mendukung pelaksanaan SDI di tingkat provinsi; 8. Membantu implementasi peningkatan integrasi simpul jaringan Jakarta Satu agar data dan layanan terdistribusi secara efisien antar unit; 9. Memberikan dukungan sharing knowledge, mentoring, dan pendampingan teknis penggunaan perangkat lunak GIS serta teknologi pendukungnya. 10. Membantu perumusan konsep dan pelaksanaan kegiatan terkait Jakarta Satu Festival; 11. Memastikan seluruh pekerjaan dikerjakan secara efektif dan efisien; 12. Melakukan koordinasi dengan tim lain Jakarta Satu untuk pengembangan geospasial Jakarta Satu; 13. Melaporkan dan mempertanggungjawabkan pelaksanaan tugas; 14. Melaporkan dan mempertanggungjawabkan pelaksanaan tugas setiap bulanan dan tahunan; 15. Melaksanakan tugas lainnya yang ditetapkan oleh pimpinan/atasan sesuai kewenangan', 'Tenaga Ahli Muda S1 Pengalaman Minimal 3 Tahun (Jasa Konsultansi Perorangan Non Konstruksi)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 47188);
