INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61457340', 61457340, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'PUSAT DATA DAN INFORMASI CIPTA KARYA, TATA RUANG DAN PERTANAHAN', 'Tenaga Ahli Publikasi dan Kehumasan (Senior Kehumasan) 1', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 122100000, 'November 2025', 'APBD', 1, 1, '1 Orang x 12 Bulan', '1) Mengelola konten pada media sosial Dinas Cipta Karya, Tata Ruang dan Pertanahan Provinsi DKI Jakarta serta Jakarta Satu. 2) Bekerjasama dan menerima arahan dari Team Leader Content Creator & Publikasi dalam mengembangkan strategi publikasi media sosial yang konsisten dan relevan dengan tren, termasuk membuat pola konten, kalender editorial, serta melakukan evaluasi performa dan engagement untuk memperkuat citra positif instansi. 3) Bekerjasama dam menerima arahan dari Team Leader Content Creator & Publikasi dan Team Leader Production & Event dalam proses produksi video kreatif mulai dari penyusunan storyboard hingga proses editing dan finishing output audiovisual. 4) Memahami layanan dan informasi yang ada di lingkungan Dinas Cipta Karya, Tata Ruang dan Pertanahan Provinsi DKI Jakarta. 5) Menyusun strategi publikasi dan kolaborasi konten edukasi lintas perangkat daerah, termasuk kegiatan bersama, event, dan kampanye sosialisasi. 6) Mengelola konten website resmi Dinas Cipta Karya, Tata Ruang dan Pertanahan Provinsi DKI Jakarta. 7) Melayani masyarakat untuk menyampaikan informasi publik yang jelas, humanis, dan mudah dipahami masyarakat. 8) Menyusun strategi efektif untuk event (seperti Kunjungan, FGD, Rapat, Sosialisasi, dll). 9) Menyusun prosedur operasional standar terkait pelaksanaan kegiatan publikasi dan event. 10) Menyusun data penyusunan keperluan device untuk kelengkapan event. 11) Supervisi kegiatan produksi konten sebagai standar kualitas pengambilan gambar konten Dinas Cipta Karya, Tata Ruang dan Pertanahan Provinsi DKI Jakarta serta Jakarta Satu. 12) Menyusun rencana strategis publikasi tentang Tata Ruang dan Bangunan. 13) Mengembangkan website Dinas Cipta Karya, Tata Ruang dan Pertanahan Provinsi DKI Jakarta dari segi publikasi dan kampanye pelayanan. 14) Mengolah website yang dimiliki Dinas Cipta Karya, Tata Ruang dan Pertanahan Provinsi DKI Jakarta. 15) Merancang tampilan website Dinas Cipta Karya, Tata Ruang dan Pertanahan Provinsi DKI Jakarta dari segi publikasi dan kampanye pelayanan. 16) Mengambil dokumentasi resmi kegiatan / event dalam bentuk foto, video, dan multimedia untuk arsip instansi. 17) Bertanggung jawab sebagai floor director pada acara Live Talkshow. 18) Menyusun laporan bulanan sebagai bahan evaluasi kinerja publikasi dan aktivitas komunikasi instansi.', 'S1 Program Studi Desain Komunikasi Visual / Ilmu Komunikasi / Arsitektur / Penyiaran / Perencanaan Wilayah dan Kota / Event / Sistem Informasi dan/atau semua jurusan yang memahami prinsip Komunikasi Visual, Tata Ruang dan Bangunan serta memiliki pengalaman minimal 3 (tiga) tahun dalam bidang Publikasi dan Kehumasan', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 47252);
