INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61460397', 61460397, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'PUSAT DATA DAN INFORMASI CIPTA KARYA, TATA RUANG DAN PERTANAHAN', 'Tenaga Ahli Pembangunan, Pengembangan dan Pengelolaan Aplikasi Cipta Karya, Tata Ruang dan Pertanahan (Tenaga Ahli Pengalaman Minimal 5 Tahun - Middle Mobile Developer)', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 141900000, 'November 2025', 'APBD', 1, 1, '1 x 12 Bulan', '1. Merancang dan mengembangkan aplikasi mobile (iOS dan Android) sesuai kebutuhan bisnis dengan fokus pada pengalaman pengguna yang intuitif, performa tinggi, dan stabilitas sistem. 2. Menerapkan arsitektur aplikasi yang scalable dan maintainable, seperti MVVM, MVP, atau Clean Architecture, agar aplikasi mudah dikembangkan dan dipelihara. 3. Mengintegrasikan aplikasi dengan backend dan layanan eksternal melalui API, memastikan sinkronisasi data berjalan lancar dan fungsionalitas sistem beroperasi dengan baik. 4. Menulis dan memelihara kode yang bersih, efisien, terdokumentasi dengan baik, serta sesuai dengan standar dan praktik terbaik pengembangan aplikasi mobile. 5. Berkoordinasi dengan tim desain, backend, dan tenaga ahli lainnya untuk menyelesaikan permasalahan teknis serta memastikan kualitas aplikasi sesuai standar organisasi. 6. Melaksanakan tugas lain yang ditetapkan oleh pimpinan atau atasan, sesuai dengan kewenangan dan kebutuhan organisasi.', 'a. S1/D4 Teknik Komputer / Teknik Informatika / Sistem Informasi / Geografi / Teknik Elektro / Teknik Geomatika / Teknik Geografi atau Program Studi Sejenis; b. Memiliki pengalaman 7 Tahun dalam bidang IT atau pengalaman sejenis; c. Memiliki NIB dengan KBLI 62019. d. Mampu mencari akar masalah dengan pendekatan yang sistematis (troubleshooting dengan pendekatan root-cause analysis); e. Mampu melakukan analisis kebutuhan serta merancang dan mengembangkan sistem aplikasi mobile yang sesuai dengan standar teknis dan kebutuhan bisnis; f. Menguasai pengembangan aplikasi iOS dan Android menggunakan Objective-C, Swift, Java, atau Kotlin; g. Memiliki pengalaman dalam penggunaan React Native atau framework pengembangan lintas platform lainnya; h. Menguasai konsep arsitektur aplikasi seperti MVC dan HMVC, serta framework pendukung berbasis PHP, JavaScript, dan CSS; i. Menguasai pengelolaan dan optimasi database (PostgreSQL, MySQL, Oracle) serta web server (Apache, Nginx); j. Mampu menjelaskan aspek teknis secara sistematis dan memberikan rekomendasi konkret/preskriptif berdasarkan hasil analisis dan evaluasi teknis.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 47376);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61538246', 61538246, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'UNIT PENGELOLA GELANGGANG  JAKARTA UTARA', 'Petugas Keamanan', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Utara (Kota)', 4463121347, 'October 2025', 'APBD', 1, 1, '12 Bulan', '1. Mengamankan semua jenis aset kantor 2. Menjaga keamanan dan ketertiban lingkungan kantor 3. Mengantisipasi/mencegah hal-hal yang tidak diinginkan di lingkungan kantor 4. Menginterogasi hal-hal yang dicurigai di lingkungan kantor 5. Berkoordinasi dengan instansi keamanan setempat 6. Mengarahkan setiap pengunjung kantor 7. Membuat laporan kendaraan pengunjung 8. Membuat rencana kerja harian, mingguan, bulanan dan tahunan 9. Membuat laporan kerja harian, mingguan, bulanan dan tahunan', 'Pendidikan Minimal SLTA/Sederajat', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 47377);
