INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61920223', 61920223, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'SUKU DINAS KOMUNIKASI, INFORMATIKA DAN STATISTIK KOTA - JAKBAR', 'Tenaga Komunikasi Informasi Publik Reporter', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Barat (Kota)', 115063650, 'November 2025', 'APBD', 1, 1, '1 Orang x 13 Bulan', 'a. Meliput kegiatan Pemerintah Kota Administrasi Jakarta Barat. b. Melakukan wawancara dengan narasumber terkait pelaksanaan kegiatan yang dilakukan. c. Membuat berita dari hasil peliputan dan wawancara dengan narasumber. d. Menginput berita yang telah dibuat di CMS website resmi Pemerintah Kota Administrasi Jakarta Barat. e. Menginformasikan berita yang telah dibuat kepada Operator Media Sosial untuk kebutuhan materi media sosial. f. Menyusun laporan dan dokumentasi pekerjaan. g. Melaksanakan tugas lain yang diperintahkan pimpinan.', 'a. Pendidikan minimal D4/S1; b. Memiliki pengalaman kerja sebagai reporter minimal 1 tahun yang dibuktikan dengan surat keterangan pengalaman kerja; c. Memiliki kemampuan dalam mencari, mengumpulkan dan menulis berita sesuai dengan kaidah jurnalistik; d. Memiliki kemampuan komunikasi/wawancara yang baik; e. Memiliki sertifikat keahlian/kompetensi di bidang jurnalistik yang dikeluarkan maksimal 2 tahun terakhir; f. Memiliki kemampuan fotografi/videografi menjadi nilai tambah; g. Diutamakan memiliki pemahaman yang baik terhadap wilayah Jakarta Barat.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 47427);
