INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61918169', 61918169, 'analyze_legacy', 'Kota Batu', 'kabkota', 'Dinas Komunikasi dan Informatika', 'Belanja Alat/Bahan untuk Kegiatan Kantor-Alat/Bahan untuk Kegiatan Kantor Lainnya', 'Barang', 'E-Purchasing', 'Jawa Timur, Batu (Kota)', 18086000, 'January 2026', 'APBD', 1, 1, '20 Unit', 'Karangan Bunga Ucapan, Tisu Basah, Tisu Wajah, Kantong Sampah, Kapur Barus Toilet, Tali Plastik Rafia', 'Karangan Bunga Ucapan Spesifikasi : Karangan Bunga Ucapan, Tisu Basah Spesifikasi : 45 sheet, Isi 3 pack, Tisu Wajah Spesifikasi : 3 Ply, 540 sheet, Kantong Sampah Spesifikasi : Plastik, Uk. 80 x 100 cm, Tebal 0,05, Isi 20 Pcs, Kapur Barus Toilet Spesifikasi : Kapur Barus Toilet, Tali Plastik Rafia Spesifikasi : Warna Hitam, Ukuran/kemasan 1 kg/roll', 0, 'med', NULL, NULL, NULL, 2, 1, 1, 1, 1, 47489);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61455884', 61455884, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'PUSAT DATA DAN INFORMASI CIPTA KARYA, TATA RUANG DAN PERTANAHAN', 'Tenaga Ahli Pembangunan, Pengembangan dan Pengelolaan Aplikasi Cipta Karya, Tata Ruang dan Pertanahan (Tenaga Ahli Pengalaman Minimal 10 Tahun - Senior Software Developer)  - 3', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 191400000, 'November 2025', 'APBD', 1, 1, '1 x 12 Bulan', '1. Menyusun dan menulis dokumentasi pengembangan program; 2. Melakukan percobaan menjalankan program dan aplikasi software untuk memastikan bahwa program akan menghasilkan informasi yang dikehendaki; 3. Melakukan atau revisi langsung, perbaikan, atau perluasan program yang ada untuk meningkatkan efisiensi operasi; 4. Menganalisis, meninjau, dan menulis ulang program, menggunakan grafik dan diagram alur kerja, dan menerapkan pengetahuan tentang kemampuan komputer, materi pelajaran, dan logika simbolik; 5. Memperbaiki kesalahan dengan membuat perubahan yang sesuai dan memeriksa kembali program untuk memastikan bahwa hasil yang diinginkan telah berhasil; 6. Berkonsultasi dengan tim untuk mengidentifikasi masalah, dan menyarankan perubahan; 7. Berkonsultasi dengan dan membantu tenaga ahli software programmer mendefinisikan dan menyelesaikan masalah dalam menjalankan program-program komputer; 8. Melakukan analisis sistem dan pemrograman tugas untuk memelihara dan mengontrol penggunaan perangkat lunak komputer sistem sebagai programmer sistem; 9. Melaksanakan tugas lainnya yang ditetapkan oleh pimpinan/atasan sesuai kewenangan.', 'a. S1/D4 Teknik Komputer / Teknik Informatika / Sistem Informasi / Geografi / Teknik Elektro / Teknik Geomatika / Teknik Geografi atau Program Studi Sejenis; b. Memiliki pengalaman 10 Tahun dalam bidang IT atau pengalaman sejenis; c. Memiliki NIB dengan KBLI 62019. d: Mampu melakukan analisis akar masalah (troubleshooting) dengan pendekatan root cause analysis secara sistematis untuk menemukan sumber permasalahan dan menetapkan solusi yang tepat; e. Mampu menganalisis dan mengevaluasi proses bisnis yang berjalan di Dinas Cipta Karya, Tata Ruang, dan Pertanahan Provinsi DKI Jakarta, serta mengidentifikasi area pengembangan dan perbaikan sistem; f. Mampu mengawasi dan memastikan pemeliharaan sistem berjalan optimal, serta memastikan perubahan proses bisnis dapat tercermin secara efektif dalam sistem aplikasi; g. Menguasai bahasa pemrograman seperti PHP (minimal versi 5), HTML, JavaScript, Java, jQuery, dan CSS, serta memahami prinsip pengembangan aplikasi berbasis web modern; h. Menguasai konsep arsitektur aplikasi seperti MVC dan HMVC, serta berpengalaman dalam penggunaan berbagai framework berbasis PHP, JavaScript, dan CSS; i. Menguasai sistem manajemen basis data (DBMS) seperti PostgreSQL, MySQL, dan diutamakan memiliki pengalaman menggunakan Oracle Database; j. Berpengalaman dalam pengelolaan dan optimasi web server, seperti Apache dan Nginx, untuk menjamin performa dan stabilitas sistem; k. Menguasai serta memiliki pengalaman bekerja dengan API Web Service dan Map Service, seperti JSON, GeoJSON, REST, dan layanan integrasi data lainnya; l. Mampu membuat, membaca, dan menganalisis alur kerja proses bisnis (business process workflow) guna memastikan sistem mendukung efisiensi dan kebutuhan organisasi; m. Mampu menjelaskan hal teknis secara sistematis dan mudah dipahami, baik kepada tim pengembang maupun pihak non-teknis, serta memberikan rekomendasi konkret dan preskriptif berdasarkan hasil analisis dan visualisasi sistem.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 47490);
