INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61856856', 61856856, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'PUSAT DATA DAN INFORMASI CIPTA KARYA, TATA RUANG DAN PERTANAHAN', 'Tenaga Sub Profesional - Assistant Professional Staff (Pengelolaan Kearsipan dan Digitalisasi Arsip Dokumen Teknis dan Perizinan Tata Ruang dan Bangunan)', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 510840000, 'December 2025', 'APBD', 1, 1, '6 Orang x 12 Bulan', 'Ruang lingkup pekerjaan Kegiatan Pengelolaan Digitalisasi Arsip Dokumen Teknis dan Perizinan Tata Ruang dan Bangunan (Assistant Professional Staff) adalah sebagai berikut : a. Melakukan input dan pengelolaan data hasil scan ke system; b. Mempertanggung jawabkan untuk memastikan kualitas produk dan informasi; c. Menjaga dan meningkatkan kinerja hasil input; d. Melakukan analisa data sesuai kebutuhan layanan terhadap produk yang akan dikembangkan; e. Memberikan dukungan mengupdate data hasil scan di lingkungan kerja Pusat Data dan Informasi Cipta Karya, Tata Ruang dan Pertanahan; f. Melakukan pencarian dan pendataan arsip-arsip dari Pelayanan Dinas Cipta Karya, Tata Ruang dan Pertanahan; g. Melakukan Quality Control dari hasil scan; h. Mengunggah hasil scan yang telah di QC ke dalam web SIKAT; i. Melakukan membuat analisa terhadap permasalahan; j. Berkonsultasi dengan tim dan membantu tenaga ahli mendefinisikan dan menyelesaikan masalah dalam menjalankan program-program komputer; k. Melaporkan dan mempertanggung jawabkan pelaksanaan tugas; l. Melaksanakan tugas lainnya yang ditetapkan oleh pimpinan/atasan sesuai kewenangan.', 'Spesifikasi Teknis Kegiatan Pengelolaan Digitalisasi Arsip Dokumen Teknis dan Perizinan Tata Ruang dan Bangunan ini adalah : a. Memahami mekanisme pengelolaan kearsipan; b. Memastikan kelengkapan setiap arsip sebelum dan sesudah digitalisasi; c. Melakukan pengecekan kualitas hasil scan (kejernihan, kesesuaian ukuran, orientasi); d. Menguasai dan Mengunggah arsip digital ke sistem ArcGis dan Web SIKAT (Sistem Informasi Kearsipan Terpadu).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 47702);
