INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61466477', 61466477, 'analyze_legacy', 'Kementerian Agama', 'central', 'IAIN MANADO 426251', 'Sewa Bandwith Internet', 'Jasa Lainnya', 'E-Purchasing', 'Sulawesi Utara, Manado (Kota)', 1850000000, 'November 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Tahun', 'Pekerjaan ini meliputi penyediaan layanan sewa bandwidth internet bagi Institut Agama Islam Negeri (IAIN) Manado) selama periode tahun anggaran berjalan. Layanan internet yang disediakan harus memiliki koneksi dedicated (symmetrical) dengan kapasitas bandwidth sesuai spesifikasi teknis yang ditetapkan, serta memiliki tingkat ketersediaan (availability) dan kecepatan akses tinggi untuk mendukung kegiatan akademik, administrasi, penelitian, dan layanan digital kampus.', '1. Jenis Layanan Dedicated Internet (Symmetrical Bandwidth), non-sharing, full-duplex. Dapat digunakan untuk seluruh jaringan kampus (terhubung ke gateway utama). Mendukung akses IPv4 dan IPv6. 2. Konektivitas Terhubung langsung ke backbone nasional/internasional (Tier-1 Provider). Redundansi jalur (backup link) disarankan untuk menjaga kestabilan koneksi. Latency ke IIX (Indonesia Internet Exchange) maksimal ≤ 10 ms. 3. Perangkat Pendukung Router, modem, dan perangkat lain disediakan oleh penyedia jasa (jika belum tersedia). Perangkat harus mendukung protokol: BGP, OSPF, dan SNMP untuk monitoring. Penyedia wajib melakukan instalasi, konfigurasi, dan integrasi dengan sistem jaringan kampus. 4. Kualitas Layanan (Service Level Agreement / SLA) Uptime minimal: 99% per bulan. Waktu respon gangguan maksimal: 30 menit sejak laporan diterima. Waktu pemulihan gangguan maksimal: 2 jam. Monitoring jaringan 24 jam x 7 hari (NOC aktif). Laporan kinerja jaringan disampaikan secara berkala (bulanan).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 47804);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61466566', 61466566, 'analyze_legacy', 'Kementerian Agama', 'central', 'IAIN MANADO 426251', 'LANGGANAN APLIKASI TURNITIN PLAGIARISM CHECKER T.A 2026', 'Jasa Lainnya', 'Pengadaan Langsung', 'Sulawesi Utara, Manado (Kota)', 280004000, 'November 2025', 'APBN - RUPIAH MURNI (A)', 1, 0, '1 Tahun', 'Pekerjaan ini meliputi penyediaan layanan langganan aplikasi Turnitin Plagiarism Checker bagi Institut Agama Islam Negeri (IAIN) Manado untuk mendukung kegiatan akademik, penelitian, dan publikasi ilmiah. Layanan ini digunakan untuk memeriksa tingkat kesamaan (similarity index) dan mendeteksi indikasi plagiarisme pada karya tulis mahasiswa, dosen, serta publikasi ilmiah institusi.', 'Pekerjaan mencakup penyediaan akun institusi, akses berbasis cloud (web-based), dukungan teknis, pelatihan penggunaan aplikasi, serta pemeliharaan dan pembaruan sistem selama masa langganan agar layanan Turnitin dapat digunakan secara optimal oleh seluruh sivitas akademika IAIN Manado.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 47805);
