INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61917861', 61917861, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'SUKU DINAS KOMUNIKASI, INFORMATIKA DAN STATISTIK KOTA - JAKBAR', 'Tenaga Komunikasi Informasi Publik Designer Grafis', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Barat (Kota)', 127992150, 'November 2025', 'APBD', 1, 1, '1 Orang x 13 Bulan', 'a. Melaksanakan perancangan kebutuhan materi grafis yang akan dipublikasikan di media resmi Pemerintah Kota Administrasi Jakarta Barat. b. Melaksanakan pembuatan dan penyuntingan grafis kebutuhan Pemerintah Kota Administrasi Jakarta Barat. c. Menginformasikan grafis yang telah dibuat kepada Operator Media Sosial untuk kebutuhan publikasi di media sosial. d. Melaksanakan dukungan penyuntingan video/audio/foto kebutuhan Pemerintah Kota Administrasi Jakarta Barat. e. Menyusun laporan dan dokumentasi pekerjaan. f. Melaksanakan tugas lain yang diperintahkan pimpinan.', 'a. Pendidikan minimal D3, diutamakan jurusan Multimedia/Desain Komunikasi Visual/Sistem Informasi/Manajemen Informatika; b. Diutamakan memiliki pengalaman kerja di bidang desain grafis yang dibuktikan dengan surat keterangan pengalaman kerja; c. Memiliki kemampuan dalam membuat materi grafis untuk kebutuhan konten media sosial dan publikasi lainnya; d. Memiliki keahlian menggunakan software editing (Adobe Photoshop, Illustrator dsb); e. Memiliki kreatifitas yang tinggi serta memahami tren sosial dan digital saat ini; f. Memiliki pemahaman yang baik dalam pemilihan warna dan aset grafis; g. Memiliki sertifikat keahlian/kompetensi di bidang desain grafis atau editing yang dikeluarkan maksimal 2 tahun terakhir; h. Memiliki kemampuan desain motion grafis menjadi nilai tambah.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 48550);
