INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61457441', 61457441, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'PUSAT DATA DAN INFORMASI CIPTA KARYA, TATA RUANG DAN PERTANAHAN', 'Tenaga Ahli Publikasi dan Kehumasan (Senior Audio Visual & Device Management)', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 122100000, 'November 2025', 'APBD', 1, 1, '1 Orang x 12 Bulan', '1. Mengelola, memelihara, dan mendukung semua infrastruktur perangkat audio visual device, mulai dari videotron, resolume arena, proyektor, display layar, TV, sistem suara, mikrofon, perangkat video conference dan instalasi hingga pemeliharaan rutin, pemecahan masalah (troubleshooting), dan pelatihan pengguna. 2. Menguasai dan mengarahkan penggunaan perangkat lunak NovaLCT, Resolume Arena, VPlex express, LEDset, Micontroller, Cubase, Audio Architect, Adobe Audition, Camtasia Audiate atau perangkat lunak lainnya 3. Mengawasi dukungan teknis untuk acara internal dan eksternal, rapat penting (seperti rapat pimpinan ), dan konferensi video, memastikan kelancaran audio dan video 4. Melaksanakan acara / kegiatan yang diselenggarakan sesuai keputusan Pusat Data dan Informasi Cipta Karya, Tata Ruang dan Pertanahan Provinsi DKI Jakarta. 5. Membuat jadwal dan membimbing tim teknisi audiovisual dan memberikan pelatihan teknis dan pengembangan profesional untuk anggota tim. 6. Bekerja sama dengan tim pengadaan untuk meneliti, merekomendasikan, dan membeli peralatan audiovisual baru. 7. Berkoordinasi dengan vendor untuk layanan perbaikan, pembelian peralatan, dan dukungan teknis khusus. 8. Mencari solusi atas masalah teknis audiovisual, perangkat keras, dan perangkat lunak. 10. Merencanakan dan mengelola instalasi perangkat audiovisual baru, serta peningkatan sistem yang sudah ada sesuai dengan perkembangan teknologi. 11. Bekerjasama dan menerima arahan dari Team Leader Production & Event dan Team Leader Content Creator & Publikasi dalam proses pra-produksi, produksi, hingga pasca produksi. 12. Mengidentifikasi tren baru dan membuat materi pelatihan dan menyelenggarakan sesi pelatihan tentang cara menggunakan peralatan audiovisual di ruang rapat secara efektif. 13. Memastikan semua peralatan audiovisual (proyektor, layar, mikrofon, speaker, sistem video conference, panel kontrol, dll.) berada dalam kondisi operasional puncak melalui pemeliharaan preventif dan pemantauan proaktif.', 'S1 Program Studi Teknik Informatika / Sistem Informasi dan/atau semua jurusan yang setara/relevan dengan pemahaman produksi konten audiovisual dan pelaksanaan acara pemerintahan serta memiliki pengalaman minimal 3 (tiga) tahun dalam bidang Publikasi dan Kehumasan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 48635);
