INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62160420', 62160420, 'analyze_legacy', 'Mahkamah Agung', 'central', 'PENGADILAN AGAMA TALU01', 'Langganan Internet', 'Jasa Lainnya', 'E-Purchasing', 'Sumatera Barat, Pasaman Barat (Kab.)', 168000000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 1, Thn, @ 168000000 )', 'Maksud dari kegiatan ini adalah melakukan pengadaan jasa langganan internet di Pengadilan Agama Talu tahun anggaran 2025 b. Tujuan dari kegiatan ini untuk memenuhi layanan kebutuhan akan penggunaan internet di Pengadilan Agama Talu 2. Gambaran Umum Sesuai dengan Lampiran Surat Kepala Biro Perencanaan dan Organisasi Nomor : 232/Bua.1/OT.01.1/6/2019 tanggal 26 juni 2019 berupa peningkatan bandwith yang regular menggunakan jasa telekomunikasi yang bersifat dedicate 1:1, 3. Ruang Lingkup Pelayanan yang harus disampaikan adalah pemenuhan kebutuhan layanan internet sesuai dengan Surat Perintah Kerja dengan Penyedia jasa dan layanan yang membutuhkan jaringan internet dapat terpenuhi dengan sempurna. 4. Lokasi Pekerjaan Kantor Pengadilan Agama Talu, Jl. Jati II, Simpang Empat Kenagarian Lingkuang Aua, Kecamatan Pasaman, Kabupaten Pasaman Barat, Provinsi Sumatera Barat 5. Strategi Pencapaian Keluaran a. Metode pelaksanaan pemilihan calon penyedia jasa dilakukan dengan metode e-katalog; b. Waktu pelaksanaan pemilihan penyedia jasa pada bulan Desember 2025; c. Keluaran yang dihasilkan berupa layanan internet selama 12 bulan penuh di Pengadilan Agama Talu mulai dari tanggal 1 Januari 2026 s.d. 31 Desember 2026 6. Persyaratan Kualifikasi Sesuai dengan Lampiran Surat Kepala Biro Perencanaan dan Organisasi 232/Bua.1/OT.01.1/6/2019 tanggal 26 juni 2019 berupa peningkatan Bandwith yang regular menggunakan jasa telekomunikasi yang bersifat dedicated 1 : 1 dengan spesifikasi : a. Bandwith Internet Dedicated 1:1 sebesar 150 Mbps b. SLA (Service Level Aggrement) minimum 95% c. IP Publik Gratis d. Koneksi akhir menggunakan RJ 45 e. MRTG untuk laporan monitoring f. Dukungan Pelayanan 24 Jam x 7 hari baik online maupun offline g. Diutamakan menggunakan fiber optic h. Maintanance web security 7. Nilai Pekerjaan Nilai pekerjaan sesuai dengan pagu anggaran adalah sebesar Rp. 168.000.000 (seratus enam puluh delapan juta rupiah) untuk pemenuhan kebutuhan layanan selama 12 bulan yang akan dilaksanakan pembayaran setiap bulannya sebesar Rp. 14.000.000 (empat belas juta rupiah) sudah termasuk pajak.', 'jasa langganan internet di Pengadilan Agama Talu tahun anggaran 2025 dengan spesifikasi : a. Bandwith Internet Dedicated 1:1 sebesar 100 Mbps b. SLA (Service Level Aggrement) minimum 95% c. IP Publik Gratis d. Koneksi akhir menggunakan RJ 45 e. MRTG untuk laporan monitoring f. Dukungan Pelayanan 24 Jam x 7 hari baik online maupun offline g. Ada backup ketika jaringan down h. Diutamakan menggunakan fiber optic i. Maintanance web security j. Diutamakan bisa support aplikasi layanan', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 48666);
