INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61920295', 61920295, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'SUKU DINAS KOMUNIKASI, INFORMATIKA DAN STATISTIK KOTA - JAKBAR', 'Tenaga Komunikasi Informasi Publik Operator Sosial Media', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Barat (Kota)', 102135150, 'November 2025', 'APBD', 1, 1, '1 Orang x 13 Bulan', 'a. Mengelola media sosial Instagram, Facebook, X dan Tik Tok Pemkot Administrasi Jakarta Barat. b. Mengupdate agenda kegiatan Walikota dan jajarannya di website Pemkot Administrasi Jakarta Barat. c. Mengupload berita foto dan video ke website Pemkot Administrasi Jakarta Barat. d. Menyusun rekap kegiatan dokumentasi bulanan. e. Menyusun laporan dan dokumentasi pekerjaan. f. Melaksanakan tugas lain yang diperintahkan Pimpinan.', 'a. Pendidikan minimal D3; b. Memiliki pengalaman kerja sebagai operator media sosial/komunikasi media minimal 1 tahun yang dibuktikan dengan surat keterangan pengalaman kerja; c. Memiliki kemampuan serta aktif dalam mengoperasikan dan mengelola media sosial; d. Memiliki skill copywriting dan kreatifitas dalam penulisan; e. Memahami tren media sosial saat ini; f. Memiliki sertifikat keahlian/kompetensi di bidang komunikasi media atau terkait pengelolaan media sosial yang dikeluarkan maksimal 2 tahun terakhir; g. Memiliki kemampuan desain grafis menjadi nilai tambah. h. Diutamakan memiliki pengalaman bekerja di pemerintahan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 49030);
