INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61460911', 61460911, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'PUSAT DATA DAN INFORMASI CIPTA KARYA, TATA RUANG DAN PERTANAHAN', 'Tenaga Ahli Pembangunan, Pengembangan dan Pengelolaan Aplikasi Cipta Karya, Tata Ruang dan Pertanahan (Tenaga Ahli Pengalaman Minimal 5 Tahun - Middle Software Developer) - 3', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 141900000, 'November 2025', 'APBD', 1, 1, '1 x 12 Bulan', '1.Menyusun dan menulis dokumentasi pengembangan program sebagai acuan dalam proses pengembangan, pemeliharaan, dan penyempurnaan sistem aplikasi. 2.Melakukan pengujian dan analisis terhadap program atau aplikasi untuk memastikan keluaran sistem sesuai dengan spesifikasi dan kebutuhan pengguna. 3.Melakukan revisi, perbaikan, serta pengembangan program yang ada guna meningkatkan efisiensi, keandalan, dan kinerja sistem. 4.Menganalisis dan menulis ulang program dengan menggunakan diagram alur kerja, logika simbolik, serta menerapkan pengetahuan tentang kemampuan komputer dan metodologi pemrograman. 5.Berkoordinasi dan berkonsultasi dengan tim teknis dan tenaga ahli terkait untuk mengidentifikasi permasalahan, memberikan solusi, dan memastikan kelancaran operasional sistem. 6.Melaksanakan tugas lain yang ditetapkan oleh pimpinan atau atasan sesuai dengan kewenangan dan tanggung jawab jabatan.', 'a. S1/D4 Teknik Komputer / Teknik Informatika / Sistem Informasi / Geografi / Teknik Elektro / Teknik Geomatika / Teknik Geografi atau Program Studi Sejenis; b. Memiliki pengalaman 5 Tahun dalam bidang IT atau pengalaman sejenis; c. Memiliki NIB dengan KBLI 62019. d. Mampu mencari akar masalah dengan pendekatan yang sistematis (troubleshooting dengan metode root-cause analysis). e. Mampu menganalisis dan mengevaluasi proses bisnis untuk mengidentifikasi kebutuhan, area pengembangan, dan perbaikan sistem aplikasi. f. Menguasai bahasa pemrograman PHP (minimal versi 5), HTML, JavaScript, Java, jQuery, CSS dan konsep arsitektur MVC/HMVC. g. Menguasai framework pengembangan berbasis PHP, JavaScript, dan CSS, serta pengalaman integrasi API Web Service dan Map Service (JSON, GeoJSON, REST, dll.). h. Menguasai pengelolaan dan optimasi database (PostgreSQL, MySQL, Oracle) serta web server (Apache, Nginx). i. Mampu membuat dan menganalisis alur kerja bisnis proses untuk mendukung pengembangan sistem yang efektif. j. Mampu menjelaskan aspek teknis secara sistematis dan memberikan rekomendasi konkret/preskriptif berdasarkan hasil analisis dan evaluasi.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 49284);
