INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61494939', 61494939, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'PUSAT DATA DAN INFORMASI CIPTA KARYA, TATA RUANG DAN PERTANAHAN', 'Tim Pembangunan, Pengembangan dan Pengelolaan Sistem Informasi Geografis Jakarta Satu - Junior Spatial Data Quality and Engineer  - 1', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 122100000, 'November 2025', 'APBD', 1, 1, '1 orang x 12 bulan', '1. Bertanggung jawab terhadap seluruh pelaksanaan pekerjaan sesuai dengan spesifikasi teknis yang ditetapkan; 2. Merencanakan, mengonsep, dan mengolah data spasial dan tabular yang ada di Jakarta Satu; 3. Melakukan kontrol kualitas terhadap pengolahan dan perbaikan data spasial dan tabular yang dilakukan; 4. Mengimplementasikan struktur data KUGI dan standarisasi lain yang ditetapkan pada data Jakarta Satu; 5. Membantu melakukan monitoring seluruh data di Jakarta Satu; 6. Mendokumentasikan dan mempublikasikan hasil statistik data Jakarta Satu dalam bentuk dashboard dan infografis; 7. Membuat engine otomatisasi dalam pengelolaan data spasial dan tabular; 8. Melakukan geocoding dalam transformasi data atribut menjadi koordinat geografis untuk keperluan analisis spasial; 9. Melakukan integrasi sistem GIS dengan sistem eksternal melalui REST API dan Web Service; 10. Melakukan monitoring data untuk mendukung pengelolaan dalam penyimpanan data geospasial; 11. Membantu melakukan analisa terhadap layanan permintaan data yang ada dalam portal Jakarta Satu; 12.Mendukung pelaksanaan SDI di tingkat provinsi; 13. Menampilkan hasil analisis data dalam bentuk materi presentasi atau visual dengan cara yang efektif dengan menggunakan software visualisasi; 14. Membantu implementasi peningkatan integrasi simpul jaringan Jakarta Satu agar data dan layanan terdistribusi secara efisien antar unit; 15. Memberikan dukungan sharing knowledge, mentoring, dan pendampingan teknis penggunaan perangkat lunak GIS serta teknologi pendukungnya; 16. Memastikan seluruh pekerjaan dikerjakan secara efektif dan efisien; 17. Melakukan koordinasi dengan tim lain Jakarta Satu untuk pengembangan geospasial Jakarta Satu; 18. Melaporkan dan mempertanggungjawabkan pelaksanaan tugas; 19. Melaporkan dan mempertanggungjawabkan pelaksanaan tugas setiap bulanan dan tahunan; 20. Melaksanakan tugas lainnya yang ditetapkan oleh pimpinan/atasan sesuai kewenangan.', 'Tenaga Ahli Muda S1 Pengalaman Minimal 3 Tahun (Jasa Konsultansi Perorangan Non Konstruksi)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 49766);
